// TypeScript / Redux-Saga: strengthen parsing for unexpected types and
// consolidate utilities while preserving behavior.

import { ResultType, StepResponse } from '@txp-core/runtime';
import { put } from 'redux-saga/effects';
import {
  PaymentChargesTableAction,
  paymentTableSelectors
} from '@txp-core/payment-transactions-table';
import { select } from '@txp-core/basic-utils';
import type { CreditChargesPaymentTypes } from '@txp-core/payment-transactions-table/dist/paymentTableStateTypes';

// Configuration
const DECIMALS = 2;

// ---------- Utilities (consolidated) ----------
// quantize: round half-up to a fixed number of decimals to avoid FP drift
const quantize = (n: number, decimals = DECIMALS): number => {
  const factor = 10 ** decimals;
  // emulate bankers-safe half-up using EPSILON guard
  return Math.round((n + Number.EPSILON) * factor) / factor;
};

// parseAmount: robust numeric parser for diverse, unexpected inputs
// - Accepts numbers, numeric-ish strings (commas, spaces, currency, parentheses for negatives)
// - Rejects booleans, null/undefined, NaN/Infinity; returns fallback on failure
// - Optionally clamps negative values to 0
const parseAmount = (
  value: unknown,
  { fallback = 0, nonNegative = false }: { fallback?: number; nonNegative?: boolean } = {}
): number => {
  // Fast-path primitives
  if (value == null) return nonNegative ? 0 : fallback;
  if (typeof value === 'boolean') return nonNegative ? 0 : fallback; // avoid true -> 1
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) return nonNegative ? 0 : fallback;
    const n = value;
    return nonNegative && n < 0 ? 0 : n;
  }

  // Attempt to stringify anything else safely
  let s: string;
  try {
    s = String((value as any)?.toString?.() ?? value);
  } catch {
    return nonNegative ? 0 : fallback;
  }

  s = s.trim();
  if (s === '') return nonNegative ? 0 : fallback;

  // Normalize unicode minus variants to ASCII hyphen
  s = s.replace(/[−–—]/g, '-');

  // Detect and strip surrounding parentheses to denote negatives, e.g. "(123.45)"
  let parenNegative = false;
  if (/^\(\s*.*\s*\)$/.test(s)) {
    parenNegative = true;
    s = s.slice(1, -1).trim();
  }

  // Remove currency symbols and any non-digit separators except [.,+- and whitespace]
  s = s.replace(/[^\d.,+\-\s\u00A0]/g, '');
  // Remove spaces (including NBSP)
  s = s.replace(/[\s\u00A0]+/g, '');

  // If both '.' and ',' exist, treat the rightmost as decimal separator
  if (s.includes('.') && s.includes(',')) {
    const lastDot = s.lastIndexOf('.');
    const lastComma = s.lastIndexOf(',');
    const decSep = lastDot > lastComma ? '.' : ',';
    const thouSep = decSep === '.' ? ',' : '.';
    s = s.split(thouSep).join('');
    s = s.replace(decSep, '.');
  } else if (s.includes(',') && !s.includes('.')) {
    // Heuristic: if 1–2 digits after last comma, treat as decimal sep, else thousands
    const last = s.lastIndexOf(',');
    const digitsAfter = s.slice(last + 1).replace(/\D/g, '').length;
    s = digitsAfter >= 1 && digitsAfter <= 2 ? s.replace(/,/g, '.') : s.replace(/,/g, '');
  } else if (s.includes('.')) {
    // If multiple dots, keep the last as decimal sep
    const count = (s.match(/\./g) || []).length;
    if (count > 1) {
      const last = s.lastIndexOf('.');
      s = s.slice(0, last).replace(/\./g, '') + '.' + s.slice(last + 1);
    }
  }

  // Extract sign only at the start
  let sign = '';
  const signMatch = s.match(/^[+\-]+/);
  if (signMatch) {
    sign = signMatch[0].includes('-') ? '-' : '+';
    s = s.slice(signMatch[0].length);
  }
  // Remove any stray non-digits/dot now
  s = s.replace(/[^\d.]/g, '');

  let normalized = (sign || '') + s;
  if (parenNegative && !normalized.startsWith('-')) normalized = '-' + normalized;

  // Final validation
  if (!/^[+\-]?\d*\.?\d+$/.test(normalized)) return nonNegative ? 0 : fallback;

  const n = Number(normalized);
  if (!Number.isFinite(n)) return nonNegative ? 0 : fallback;

  const result = nonNegative && n < 0 ? 0 : n;
  return result;
};

// formatAmount: stable formatter producing trimmed decimal strings
const formatAmount = (n: number, decimals = DECIMALS): string => {
  const q = quantize(n, decimals);
  const s = q.toFixed(decimals).replace(/\.?0+$/, '');
  return s === '' ? '0' : s;
};

export function* outstandingTransactionsHandler(): Generator<any, StepResponse, any> {
  try {
    const creditTableLines: CreditChargesPaymentTypes[] =
      (yield* select(paymentTableSelectors.getCredits)) ?? [];

    const totalOfChargesTableRaw: unknown =
      yield* select(paymentTableSelectors.getTotalOfChargesTable);

    // Normalize inputs and guard against invalid data
    let remaining = parseAmount(totalOfChargesTableRaw, { fallback: 0, nonNegative: true });

    // Fast path: nothing to do
    if (!Array.isArray(creditTableLines) || creditTableLines.length === 0) {
      return { result: ResultType.SUCCESS };
    }

    let didChange = false;

    const updatedCreditTable: CreditChargesPaymentTypes[] = creditTableLines.map((credit) => {
      const next: CreditChargesPaymentTypes = { ...credit };

      // "Checked" means linkedPaymentAmount is a non-empty string (including "0")
      const isChecked = String(credit?.linkedPaymentAmount ?? '') !== '';

      if (!isChecked) {
        return next; // Unchecked rows are not modified
      }

      const openBalance = parseAmount(credit?.openBalance, { fallback: 0, nonNegative: true });

      if (remaining <= 0) {
        // Match original semantics: clear when nothing left to allocate
        if (next.linkedPaymentAmount !== '') {
          next.linkedPaymentAmount = '';
          didChange = true;
        }
        return next;
      }

      // Allocate up to the open balance
      const allocation = Math.min(openBalance, remaining);
      const formatted = formatAmount(allocation, DECIMALS);

      if (next.linkedPaymentAmount !== formatted) {
        next.linkedPaymentAmount = formatted;
        didChange = true;
      }

      // Decrease remaining with quantization to avoid FP drift
      remaining = quantize(remaining - allocation, DECIMALS);
      if (remaining < 0) remaining = 0;

      return next;
    });

    if (didChange) {
      yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCreditTable));
    }

    return { result: ResultType.SUCCESS };
  } catch (err) {
    return {
      result: ResultType.FAILURE,
      message: 'Unable to allocate outstanding transactions'
    } as StepResponse;
  }
}
