// Optimized, JS/TS-friendly parsing utilities for Redux-Saga usage.
// Focus: faster string normalization and simpler numeric handling while preserving robustness.

import { Decimal } from 'decimal.js-light';

export const DECIMALS = 2 as const;

// Cache powers of 10 for quantization
const POW10: Record<number, Decimal> = {};
const q = (d: number): Decimal => (POW10[d] ??= new Decimal(10).pow(-d));

const DIGITS = new Set('0123456789');
const UNICODE_MINUSES = new Set(['−', '–', '—']);

// Lightweight filter: keep only ASCII digits, '.', ',', '\'', '+', '-', '(', ')', and strip spaces (incl. NBSP)
const stripToNumericAscii = (raw: unknown): string => {
  if (raw == null) return '';
  let s: string;
  try {
    s = String(raw).trim();
  } catch {
    return '';
  }
  if (!s) return '';

  // Normalize Unicode minus to '-'
  UNICODE_MINUSES.forEach((m) => {
    if (s.includes(m)) s = s.replaceAll(m, '-');
  });

  // Remove spaces and NBSP
  s = s.replace(/\u00A0|\s+/g, '');
  if (!s) return '';

  // Fast path: if all chars already allowed, return
  const allowed = new Set([".", ",", "'", "+", "-", "(", ")", ...DIGITS]);
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (!allowed.has(c)) {
      // Fallback: rebuild keeping only allowed
      let out = '';
      for (let j = 0; j < s.length; j++) {
        const ch = s[j];
        if (allowed.has(ch)) out += ch;
      }
      return out;
    }
  }
  return s;
};

// Normalize a numeric-looking string into a Decimal-friendly form.
// Rules:
// - Parentheses denote negatives
// - Apostrophes and thousands separators are removed
// - If both '.' and ',' occur, the rightmost is the decimal separator
// - If only ',' occurs: treat as decimal if it has 1–2 trailing digits, else thousands
const normalizeNumericString = (s: string): string | null => {
  if (!s) return null;

  let negParen = s.startsWith('(') && s.endsWith(')');
  if (negParen) s = s.slice(1, -1);
  if (!s) return null;

  let sign = '';
  if (s[0] === '+' || s[0] === '-') {
    sign = s[0];
    s = s.slice(1);
  }
  if (!s) return null;

  // Keep only digits and separators here
  let tmp = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (DIGITS.has(c) || c === '.' || c === ',' || c === "'") tmp += c;
  }
  s = tmp;
  if (!s) return null;

  // Remove apostrophes (thousands)
  if (s.includes("'")) s = s.replace(/'/g, '');

  const hasDot = s.includes('.');
  const hasComma = s.includes(',');

  if (hasDot && hasComma) {
    const lastDot = s.lastIndexOf('.');
    const lastComma = s.lastIndexOf(',');
    const dotIsDecimal = lastDot > lastComma;
    if (dotIsDecimal) {
      s = s.replace(/,/g, '');
      if ((s.match(/\./g) || []).length > 1) {
        const last = s.lastIndexOf('.');
        s = s.slice(0, last).replace(/\./g, '') + '.' + s.slice(last + 1);
      }
    } else {
      s = s.replace(/\./g, '');
      if ((s.match(/,/g) || []).length > 1) {
        const last = s.lastIndexOf(',');
        s = s.slice(0, last).replace(/,/g, '') + '.' + s.slice(last + 1);
      } else {
        s = s.replace(',', '.');
      }
    }
  } else if (hasComma) {
    const last = s.lastIndexOf(',');
    let digitsAfter = 0;
    for (let i = last + 1; i < s.length; i++) if (DIGITS.has(s[i])) digitsAfter++;
    if (digitsAfter >= 1 && digitsAfter <= 2) {
      if ((s.match(/,/g) || []).length > 1) {
        s = s.slice(0, last).replace(/,/g, '') + '.' + s.slice(last + 1);
      } else {
        s = s.replace(',', '.');
      }
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (hasDot) {
    const matches = s.match(/\./g);
    if (matches && matches.length > 1) {
      const last = s.lastIndexOf('.');
      s = s.slice(0, last).replace(/\./g, '') + '.' + s.slice(last + 1);
    }
  }

  // Must have at least one digit
  if (!/[0-9]/.test(s)) return null;

  // Edge cases: ".5" -> "0.5", "123." -> "123.0"
  if (s.startsWith('.')) s = '0' + s;
  if (s.endsWith('.')) s = s + '0';

  if (negParen || sign === '-') return '-' + s;
  if (sign === '+') return '+' + s;
  return s;
};

export const parseDecimal = (
  value: unknown,
  opts?: { fallback?: Decimal; decimals?: number | null; nonNegative?: boolean }
): Decimal => {
  const fallback = opts?.fallback ?? new Decimal(0);
  const decimals = opts?.decimals ?? null;
  const nonNegative = opts?.nonNegative ?? false;

  let result: Decimal;

  // Fast paths for common primitives
  if (value == null || typeof value === 'boolean') {
    result = fallback;
  } else if (value instanceof Decimal) {
    result = value;
  } else if (typeof value === 'number') {
    result = Number.isFinite(value) ? new Decimal(value) : fallback;
  } else if (typeof value === 'bigint') {
    result = new Decimal(value.toString());
  } else {
    const s = stripToNumericAscii(value);
    if (!s) return fallback;

    // Ultra-fast direct path for plain numbers with optional leading sign and max one dot
    const first = s[0];
    const hasSign = first === '+' || first === '-';
    const core = hasSign ? s.slice(1) : s;
    const isPlain = core.length > 0 && core.indexOf(',') === -1 && core.indexOf("'") === -1 && (core.indexOf('.') === core.lastIndexOf('.')) && /^[0-9.]+$/.test(core);

    if (isPlain) {
      let plain = (hasSign ? first : '') + core;
      if (plain.startsWith('.') || plain.startsWith('-.') || plain.startsWith('+.')) plain = plain.replace('.', '0.');
      if (plain.endsWith('.')) plain += '0';
      try {
        result = new Decimal(plain);
      } catch {
        return fallback;
      }
    } else {
      const norm = normalizeNumericString(s);
      if (!norm) return fallback;
      try {
        result = new Decimal(norm);
      } catch {
        return fallback;
      }
    }
  }

  if (nonNegative && result.isNegative()) result = new Decimal(0);
  if (decimals != null) result = result.toDecimalPlaces(decimals, Decimal.ROUND_HALF_UP);
  return result;
};

export const formatAmount = (value: Decimal, decimals: number = DECIMALS): string => {
  const qv = value.toDecimalPlaces(decimals, Decimal.ROUND_HALF_UP);
  const s = qv.toFixed(decimals);
  // Trim trailing zeros and optional decimal point
  const trimmed = s.replace(/\.0+$/, '').replace(/\.$/, '');
  return trimmed === '' ? '0' : trimmed;
};
