// ---------------- Utility: trim and tokenize (data processing) ----------------
static inline std::string trim(std::string s) {
    auto not_space = [](unsigned char c){ return !std::isspace(c); };
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), not_space));
    s.erase(std::find_if(s.rbegin(), s.rend(), not_space).base(), s.end());
    return s;
}

static inline std::vector<std::string> tokenize(const std::string& text) {
    std::vector<std::string> tokens;
    std::string cur;
    for (unsigned char ch : text) {
        if (std::isalpha(ch)) cur.push_back(std::tolower(ch));
        else if (!cur.empty()) { tokens.push_back(cur); cur.clear(); }
    }
    if (!cur.empty()) tokens.push_back(cur);
    return tokens;
}

// ---------------- Encapsulated value object with operator overloading ---------
class Dimension {
private:
    double width_{0}, height_{0}, depth_{0};
public:
    Dimension() = default;
    Dimension(double w, double h, double d) : width_(w), height_(h), depth_(d) {}

    double width() const { return width_; }
    double height() const { return height_; }
    double depth() const { return depth_; }

    double volume() const { return width_ * height_ * depth_; }

    // Operator overloading: combine dimensions (component-wise)
    Dimension operator+(const Dimension& other) const {
        return Dimension(width_ + other.width_, height_ + other.height_, depth_ + other.depth_);
    }
    // Scale
    Dimension operator*(double s) const { return Dimension(width_*s, height_*s, depth_*s); }
    friend Dimension operator*(double s, const Dimension& d) { return d * s; }

    friend std::ostream& operator<<(std::ostream& os, const Dimension& d) {
        os << d.width_ << "x" << d.height_ << "x" << d.depth_ << " (vol=" << d.volume() << ")";
        return os;
    }
};

