// ---------------- Templates: Repository<T> and Analyzer<T> --------------------

template <typename T>
class Repository {
private:
    std::vector<T> items_;
public:
    void add(const T& item) { items_.push_back(item); }
    void add(T&& item) { items_.push_back(std::move(item)); }

    template <typename It>
    void addRange(It first, It last) { items_.insert(items_.end(), first, last); }

    const std::vector<T>& items() const { return items_; }

    template <typename Pred>
    std::vector<T> where(Pred p) const {
        std::vector<T> out;
        for (const auto& x : items_) if (p(x)) out.push_back(x);
        return out;
    }
};

template <typename T>
class Analyzer {
public:
    // Generic aggregation: average of a numeric projection
    template <typename F>
    static std::optional<double> average(const std::vector<T>& data, F proj) {
        if (data.empty()) return std::nullopt;
        double sum = 0.0; size_t n = 0;
        for (const auto& x : data) { sum += static_cast<double>(proj(x)); ++n; }
        return n ? std::optional<double>{sum / n} : std::nullopt;
    }

    // Count by key function (like group-by)
    template <typename KeyFn>
    static std::unordered_map<std::string, size_t> countBy(const std::vector<T>& data, KeyFn keyfn) {
        std::unordered_map<std::string, size_t> freq;
        for (const auto& x : data) ++freq[keyfn(x)];
        return freq;
    }
};

// ---------------- Museum class (manages exhibits; uses polymorphism) ---------
class Museum {
private:
    std::vector<std::unique_ptr<Exhibit>> exhibits_;
public:
    // Overloaded add methods
    void add(std::unique_ptr<Exhibit> ex) { exhibits_.push_back(std::move(ex)); }
    template <typename E, typename... Args>
    void addEmplace(Args&&... args) { exhibits_.push_back(std::make_unique<E>(std::forward<Args>(args)...)); }

    // Polymorphic display
    void showAll() const {
        for (const auto& e : exhibits_) e->display();
    }

    const std::vector<std::unique_ptr<Exhibit>>& data() const { return exhibits_; }

    // Data processing: compute global word frequency from exhibit names
    std::unordered_map<std::string, size_t> nameWordFrequency() const {
        std::unordered_map<std::string, size_t> freq;
        for (const auto& e : exhibits_) {
            for (const auto& tok : tokenize(e->getName())) ++freq[tok];
        }
        return freq;
    }

    // Data analysis: average rating across all exhibits
    std::optional<double> overallAverageRating() const {
        std::vector<double> avgs;
        for (const auto& e : exhibits_) if (auto a = e->averageRating()) avgs.push_back(*a);
        if (avgs.empty()) return std::nullopt;
        double sum = std::accumulate(avgs.begin(), avgs.end(), 0.0);
        return sum / avgs.size();
    }
};

