# lib/pages/password_page.dart
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../state/onboarding_state.dart';
import '../services/auth_service.dart';
import 'name_page.dart';

class PasswordPage extends StatefulWidget {
  static const routeName = '/password';
  const PasswordPage({super.key});

  @override
  State<PasswordPage> createState() => _PasswordPageState();
}

class _PasswordPageState extends State<PasswordPage> {
  final _formKey = GlobalKey<FormState>();
  final _pwdCtrl = TextEditingController();
  final _confirmCtrl = TextEditingController();
  bool _loading = false;
  final _auth = AuthService();

  @override
  void dispose() {
    _pwdCtrl.dispose();
    _confirmCtrl.dispose();
    super.dispose();
  }

  Future<void> _createAccount() async {
    final onboarding = context.read<OnboardingState>();
    final email = onboarding.email;
    if (email == null || email.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Missing email from previous step')),
      );
      Navigator.pop(context);
      return;
    }
    if (!_formKey.currentState!.validate()) return;

    setState(() => _loading = true);
    try {
      await _auth.signUpWithEmailAndPassword(
        email: email,
        password: _pwdCtrl.text,
      );
      onboarding.setPassword(_pwdCtrl.text);
      if (!mounted) return;
      Navigator.pushNamed(context, NamePage.routeName);
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Sign up failed: $e')),
      );
    } finally {
      if (mounted) setState(() => _loading = false);
    }
  }

  String? _validatePassword(String? v) {
    if (v == null || v.isEmpty) return 'Password required';
    if (v.length < 6) return 'Min 6 characters';
    return null;
  }

  @override
  Widget build(BuildContext context) {
    final email = context.watch<OnboardingState>().email ?? '';
    return Scaffold(
      appBar: AppBar(title: const Text('Set Password')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            Text('Creating account for: $email'),
            const SizedBox(height: 12),
            Form(
              key: _formKey,
              child: Column(
                children: [
                  TextFormField(
                    controller: _pwdCtrl,
                    decoration: const InputDecoration(labelText: 'Password'),
                    obscureText: true,
                    validator: _validatePassword,
                  ),
                  TextFormField(
                    controller: _confirmCtrl,
                    decoration: const InputDecoration(labelText: 'Confirm Password'),
                    obscureText: true,
                    validator: (v) {
                      if (v != _pwdCtrl.text) return 'Passwords do not match';
                      return _validatePassword(v);
                    },
                  ),
                ],
              ),
            ),
            const SizedBox(height: 24),
            _loading
                ? const CircularProgressIndicator()
                : ElevatedButton(onPressed: _createAccount, child: const Text('Next')),
          ],
        ),
      ),
    );
  }
}
