import 'profile_page.dart';

class ProfileDetailsPage extends StatefulWidget {
  static const routeName = '/profile_details';
  const ProfileDetailsPage({super.key});

  @override
  State<ProfileDetailsPage> createState() => _ProfileDetailsPageState();
}

class _ProfileDetailsPageState extends State<ProfileDetailsPage> {
  final _formKey = GlobalKey<FormState>();
  final _weightCtrl = TextEditingController();
  final _heightCtrl = TextEditingController();
  final _bodyCtrl = TextEditingController();
  final _picker = ImagePicker();

  File? _photoFile;
  bool _saving = false;

  final _auth = AuthService();
  final _storage = StorageService();
  final _repo = UserRepository();

  @override
  void dispose() {
    _weightCtrl.dispose();
    _heightCtrl.dispose();
    _bodyCtrl.dispose();
    super.dispose();
  }

  Future<void> _pick(ImageSource source) async {
    try {
      final picked = await _picker.pickImage(source: source, imageQuality: 85);
      if (picked != null) setState(() => _photoFile = File(picked.path));
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to pick image: $e')),
      );
    }
  }

  String? _numValidator(String? v, String name) {
    if (v == null || v.trim().isEmpty) return '$name is required';
    final d = double.tryParse(v.trim());
    if (d == null || d <= 0) return 'Enter a valid $name';
    return null;
  }

  Future<void> _save() async {
    final onboarding = context.read<OnboardingState>();
    if (onboarding.firstName == null || onboarding.lastName == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Missing name from the previous step')),
      );
      Navigator.pop(context);
      return;
    }

    if (!_formKey.currentState!.validate()) return;

    final user = _auth.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('No authenticated user. Please sign up again.')),
      );
      return;
    }

    setState(() => _saving = true);
    try {
      String? photoUrl;
      if (_photoFile != null) {
        photoUrl = await _storage.uploadUserProfilePhoto(uid: user.uid, file: _photoFile!);
      }

      final weight = double.parse(_weightCtrl.text.trim());
      final height = double.parse(_heightCtrl.text.trim());
      final bodyType = _bodyCtrl.text.trim();

      // Update Firebase Auth profile with displayName/photoURL
      final displayName = '${onboarding.firstName!} ${onboarding.lastName!}'.trim();
      await _auth.updateProfile(displayName: displayName, photoURL: photoUrl);

      // Save extended profile to Firestore
      await _repo.saveUserProfile(
        uid: user.uid,
