// lib/pages/profile_details_page.dart
import 'dart:io';
import 'package:flutter/material.dart';
import 'package:image_picker/image_picker.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_storage/firebase_storage.dart';

import 'profile_page.dart';

class ProfileDetailsPage extends StatefulWidget {
  static const routeName = '/profile_details';
  const ProfileDetailsPage({super.key});

  @override
  State<ProfileDetailsPage> createState() => _ProfileDetailsPageState();
}

class _ProfileDetailsPageState extends State<ProfileDetailsPage> {
  final _formKey = GlobalKey<FormState>();
  final _weightCtrl = TextEditingController();
  final _heightCtrl = TextEditingController();
  final _bodyCtrl = TextEditingController();
  final _picker = ImagePicker();

  File? _photoFile;
  bool _saving = false;

  @override
  void dispose() {
    _weightCtrl.dispose();
    _heightCtrl.dispose();
    _bodyCtrl.dispose();
    super.dispose();
  }

  Future<void> _pick(ImageSource source) async {
    try {
      final picked = await _picker.pickImage(source: source, imageQuality: 85);
      if (picked != null) {
        setState(() => _photoFile = File(picked.path));
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to pick image: $e')),
      );
    }
  }

  String? _numValidator(String? v, String name) {
    final value = v?.trim() ?? '';
    if (value.isEmpty) return '$name is required';
    final d = double.tryParse(value);
    if (d == null || d <= 0) return 'Enter a valid $name';
    return null;
  }

  Future<void> _save() async {
    if (!_formKey.currentState!.validate()) return;

    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      ScaffoldMessenger.of(context)
          .showSnackBar(const SnackBar(content: Text('Not signed in')));
      return;
    }

    setState(() => _saving = true);
    try {
      // Upload optional profile photo to Storage
      String? photoUrl;
      if (_photoFile != null) {
        final ref = FirebaseStorage.instance
            .ref()
            .child('users/${user.uid}/profile.jpg');
        await ref.putFile(_photoFile!);
        photoUrl = await ref.getDownloadURL();
      }

      final weight = double.parse(_weightCtrl.text.trim());
      final height = double.parse(_heightCtrl.text.trim());
      final bodyType = _bodyCtrl.text.trim();

      // Save to Firestore: users/<uid>
      await FirebaseFirestore.instance.collection('users').doc(user.uid).set({
        'email': user.email ?? '',
        'weight': weight,
        'height': height,
        'bodyType': bodyType,
        if (photoUrl != null) 'photoUrl': photoUrl,
        'updatedAt': FieldValue.serverTimestamp(),
        'createdAt': FieldValue.serverTimestamp(),
      }, SetOptions(merge: true));

      if (!mounted) return;
      Navigator.pushNamedAndRemoveUntil(
        context,
        ProfilePage.routeName,
        (_) => false,
      );
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Failed to save: $e')),
      );
    } finally {
      if (mounted) setState(() => _saving = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Profile Details')),
      body: SingleChildScrollView(
        padding: const EdgeInsets.all(16),
        child: Column(
          children: [
            Center(
              child: Stack(
                children: [
                  CircleAvatar(
                    radius: 56,
                    backgroundColor: Colors.grey.shade300,
                    backgroundImage:
                        _photoFile != null ? FileImage(_photoFile!) : null,
                    child: _photoFile == null
                        ? const Icon(Icons.person, size: 48, color: Colors.white)
                        : null,
                  ),
                  Positioned(
                    bottom: -6,
                    right: -6,
                    child: Row(
                      children: [
                        IconButton(
                          icon: const Icon(Icons.photo, color: Colors.blue),
                          onPressed: () => _pick(ImageSource.gallery),
                          tooltip: 'Pick from gallery',
                        ),
                        IconButton(
                          icon: const Icon(Icons.photo_camera, color: Colors.blue),
                          onPressed: () => _pick(ImageSource.camera),
                          tooltip: 'Take a photo',
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 16),
            Form(
              key: _formKey,
              child: Column(
                children: [
                  TextFormField(
                    controller: _weightCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Weight (kg)',
                      hintText: 'e.g. 70',
                    ),
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    validator: (v) => _numValidator(v, 'Weight'),
                  ),
                  const SizedBox(height: 12),
                  TextFormField(
                    controller: _heightCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Height (cm)',
                      hintText: 'e.g. 175',
                    ),
                    keyboardType:
                        const TextInputType.numberWithOptions(decimal: true),
                    validator: (v) => _numValidator(v, 'Height'),
                  ),
                  const SizedBox(height: 12),
                  TextFormField(
                    controller: _bodyCtrl,
                    decoration: const InputDecoration(
                      labelText: 'Body Type',
                      hintText: 'e.g. Athletic',
                    ),
                    validator: (v) {
                      final value = v?.trim() ?? '';
                      if (value.isEmpty) return 'Body type is required';
                      if (value.length < 3) return 'Enter a valid body type';
                      return null;
                    },
                  ),
                ],
              ),
            ),
            const SizedBox(height: 24),
            _saving
                ? const CircularProgressIndicator()
                : SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: _save,
                      icon: const Icon(Icons.check),
                      label: const Text('Save and Continue'),
                    ),
                  ),
          ],
        ),
      ),
    );
  }
}
```

```dart
// lib/pages/profile_page.dart
import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';

class ProfilePage extends StatelessWidget {
  static const routeName = '/profile';
  const ProfilePage({super.key});

  @override
  Widget build(BuildContext context) {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) {
      return Scaffold(
        appBar: AppBar(title: const Text('Profile')),
        body: const Center(child: Text('Not signed in')),
      );
    }

    final docStream =
        FirebaseFirestore.instance.collection('users').doc(user.uid).snapshots();

    return Scaffold(
      appBar: AppBar(title: const Text('Your Profile')),
      body: StreamBuilder<DocumentSnapshot<Map<String, dynamic>>>(
        stream: docStream,
        builder: (context, snap) {
          if (snap.connectionState == ConnectionState.waiting) {
            return const Center(child: CircularProgressIndicator());
          }
          if (snap.hasError) {
            return Center(child: Text('Error: ${snap.error}'));
          }
          final data = snap.data?.data() ?? {};
          final photoUrl = data['photoUrl'] as String?;
          final firstName = data['firstName'] as String? ?? '';
          final lastName = data['lastName'] as String? ?? '';
          final email = data['email'] as String? ?? user.email ?? '';
          final weight = (data['weight'] as num?)?.toDouble();
          final height = (data['height'] as num?)?.toDouble();
          final bodyType = data['bodyType'] as String? ?? '';

          final displayName = '$firstName $lastName'.trim();

          return SingleChildScrollView(
            padding: const EdgeInsets.all(16),
            child: Column(
              children: [
                CircleAvatar(
                  radius: 56,
                  backgroundColor: Colors.grey.shade300,
                  backgroundImage: (photoUrl != null && photoUrl.isNotEmpty)
                      ? NetworkImage(photoUrl)
                      : null,
                  child: (photoUrl == null || photoUrl.isEmpty)
                      ? (displayName.isNotEmpty
                          ? Text(
                              displayName
                                  .split(' ')
                                  .where((s) => s.isNotEmpty)
                                  .map((s) => s[0].toUpperCase())
                                  .take(2)
                                  .join(),
                              style: const TextStyle(
                                  fontSize: 28, color: Colors.white),
                            )
                          : const Icon(Icons.person,
                              size: 48, color: Colors.white))
                      : null,
                ),
                const SizedBox(height: 12),
                Text(
                  displayName.isEmpty ? 'Unnamed User' : displayName,
                  style: Theme.of(context).textTheme.headlineSmall,
                ),
                const SizedBox(height: 4),
                Text(email),
                const SizedBox(height: 16),
                Card(
                  child: Padding(
                    padding: const EdgeInsets.all(16),
                    child: Column(
                      children: [
                        _row('Weight', weight != null ? '$weight kg' : '—'),
                        const Divider(),
                        _row('Height', height != null ? '$height cm' : '—'),
                        const Divider(),
                        _row('Body Type', bodyType.isNotEmpty ? bodyType : '—'),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }

  Widget _row(String label, String value) {
    return Row(
      children: [
        Expanded(
          child: Text(label, style: const TextStyle(fontWeight: FontWeight.w600)),
        ),
        Text(value),
      ],
    );
  }
}
```

Notes:
- Storage path: users/<uid>/profile.jpg; Firestore doc: users/<uid> with fields email, weight, height, bodyType, and photoUrl.
- After successful save on ProfileDetailsPage, navigation uses pushNamedAndRemoveUntil to land on ProfilePage and clear the back stack.
- This complements the earlier RegisterPage and route wiring: RegisterPage → ProfileDetailsPage → ProfilePage.
